/// Make Vertical's `follow: speaker` (road map "creator-jobs" VR6b, spec §11 VR-64, VR-66): which
/// tracks are microphones, which pictures are framed by who is talking and with which of them,
/// the turns filled on main, and what the sheet reads to confirm the match. The step itself is
/// `VerticalVersion+Plan.swift`'s; the match is the core's (`ReelProject.speakerMatch`, VR-65).
/// Swift restates none of VR-60's refusals: a microphone the core will not take reaches the
/// clip's entry in its own sentence. Names no `rc_*`.
extension VerticalVersion {
    /// A track the sheet offers as a microphone (VR-66 (b)): its name, and the clip that stands
    /// for it in `mics`, the earliest that plays a sound file.
    struct Microphone: Equatable {
        let track: UInt32
        let name: String
        let clip: UInt32
    }

    /// A picture framed by who is talking (VR-64 (b)), with its own microphones — one clip per
    /// microphone track that sounds under it, in `mics`' order — and their faces when given.
    struct SpeakerClip: Equatable {
        let clip: UInt32
        let mics: [UInt32]
        let micFaces: [UInt32]?
    }

    /// A clip the step framed with `speaker` (VR-64 (f)): its microphones and the face of each,
    /// given or the core's own match.
    struct SpeakerFraming: Equatable {
        let clip: UInt32
        let mics: [UInt32]
        let faces: [UInt32]
    }

    /// What the sheet reads for Speaker (VR-66 (c)): a refusal's sentence, or the subjects with
    /// their turns, the reference clip and the core's match on it.
    enum SpeakerReading {
        case refused(String)
        case ready(subjects: [UInt32: [String: Any]], reference: UInt32, match: SpeakerMatch?)
    }

    /// The tool's refusal with no speaker clip (VR-64 (e)).
    static let noSpeakerClip =
        "make_vertical_version found no full-frame movie clip playing beside two of the "
        + "microphones in mics, so nobody is framed by who is talking."

    /// The sheet's sentence with no speaker clip (VR-66 (c)).
    static let noSpeakerClipSheet =
        "No full-frame movie clip plays beside two of the ticked microphones, so nobody can be "
        + "framed by who is talking."

    /// VR-66 (b): each track, front to back, holding a clip `SpeakerSwitch.playsSound` takes
    /// whose media has no picture; its `clip` the earliest such clip (ties: the lower id).
    static func microphones(_ project: ReelProject) -> [Microphone] {
        let snapshot = project.snapshot
        return snapshot.tracks.reversed().compactMap { track in
            let sounding = snapshot.clips(onTrack: track.id).filter {
                SpeakerSwitch.playsSound($0, in: snapshot)
                    && snapshot.media(for: $0)?.hasVideo == false
            }
            guard let first = sounding.min(by: { ($0.start, $0.id) < ($1.start, $1.id) })
            else { return nil }
            return Microphone(track: track.id, name: track.name, clip: first.id)
        }
    }

    /// VR-64 (b): the present, cursor-free class-3 media pictures off the microphone tracks whose
    /// span overlaps a clip with audio on at least two of them, in id order; [] unless `follow`
    /// is `speaker`. Each one's `mics` are, per microphone in order, the media clip with audio on
    /// that microphone's track with the greatest overlap (ties: the earlier start, then the lower
    /// id); a track with none is left out with its `micFaces` entry. A `micFaces` that is not
    /// one per microphone is passed as given, for the core to refuse in its own sentence.
    static func speakerClips(
        _ project: ReelProject, settings: VerticalSettings, missing: Set<UInt32>
    ) -> [SpeakerClip] {
        guard settings.follow == .speaker else { return [] }
        let snapshot = project.snapshot
        let micTracks = settings.mics.map { snapshot.clip($0)?.track }
        let onMics = Set(micTracks.compactMap { $0 })
        let given = settings.micFaces
        let filters = given.map { $0.count == settings.mics.count } ?? false
        var out: [SpeakerClip] = []
        for id in mediaPictures(classify(project), in: snapshot) where !missing.contains(id) {
            guard let clip = snapshot.clip(id), snapshot.media(for: clip)?.cursor == nil,
                !onMics.contains(clip.track)
            else { continue }
            var mics: [UInt32] = []
            var faces: [UInt32] = []
            for (n, track) in micTracks.enumerated() {
                guard let track, let best = loudest(on: track, under: clip, in: snapshot)
                else { continue }
                mics.append(best)
                if filters, let given { faces.append(given[n]) }
            }
            guard mics.count >= 2 else { continue }
            out.append(SpeakerClip(clip: id, mics: mics, micFaces: filters ? faces : given))
        }
        return out
    }

    /// The media clip with audio on `track` that overlaps `clip` most (ties: the earlier start,
    /// then the lower id); nil when none overlaps it.
    private static func loudest(
        on track: UInt32, under clip: ClipSnapshot, in snapshot: ProjectSnapshot
    ) -> UInt32? {
        func overlap(_ other: ClipSnapshot) -> Ticks {
            max(0, min(other.end, clip.end) - max(other.start, clip.start))
        }
        let sounding = snapshot.clips(onTrack: track).filter { other in
            guard case .media = other.source, snapshot.media(for: other)?.hasAudio == true
            else { return false }
            return overlap(other) > 0
        }
        return sounding.min { a, b in
            (-overlap(a), a.start, a.id) < (-overlap(b), b.start, b.id)
        }?.id
    }

    /// VR-64 (d): each speaker clip's subjects with `turns`, read through `FramingSpeaker.turns`
    /// over its own microphones; a clip with no subjects is left as it is. Main thread (it reads
    /// the document); throws `FramingSpeaker.Refusal`.
    static func withTurns(
        _ subjects: [UInt32: [String: Any]], speaker: [SpeakerClip], document: ProjectDocument
    ) throws -> [UInt32: [String: Any]] {
        var out = subjects
        let snapshot = document.editedProject.snapshot
        for entry in speaker {
            guard var own = out[entry.clip], let clip = snapshot.clip(entry.clip) else { continue }
            own["turns"] = try FramingSpeaker.turns(
                document: document, clip: clip, mics: entry.mics)
            out[entry.clip] = own
        }
        return out
    }

    /// VR-66 (c): the sheet's reading for Speaker on `project` with the ticked microphones in
    /// `settings.mics` — the turns filled, then the core's match on the reference clip (the
    /// longest speaker clip, ties to the lower id) with its own microphones. Main thread.
    static func speakerReading(
        document: ProjectDocument, project: ReelProject, settings: VerticalSettings,
        subjects: [UInt32: [String: Any]], missing: Set<UInt32>
    ) -> SpeakerReading {
        let clips = speakerClips(project, settings: settings, missing: missing)
        let snapshot = project.snapshot
        let reference = clips.min { a, b in
            let (da, db) = (snapshot.clip(a.clip)?.duration ?? 0, snapshot.clip(b.clip)?.duration ?? 0)
            return (-da, a.clip) < (-db, b.clip)
        }
        guard let reference else { return .refused(noSpeakerClipSheet) }
        let filled: [UInt32: [String: Any]]
        do {
            filled = try withTurns(subjects, speaker: clips, document: document)
        } catch let refusal as FramingSpeaker.Refusal {
            return .refused(refusal.sentence)
        } catch {
            return .refused(error.localizedDescription)
        }
        let match = filled[reference.clip].flatMap {
            project.speakerMatch(clip: reference.clip, mics: reference.mics, subjects: $0)
        }
        return .ready(subjects: filled, reference: reference.clip, match: match)
    }
}
/// after its analysis (`restoring`) opens on the hand-off's shape, follow, zoom, where empty,
/// copy and ticked microphones. At `viewDidAppear` the sheet splits the media pictures by
/// `analysisTargets` and asks `FramingAnalysis.requests` what is missing. With nothing missing it
/// reads the subjects off main ("Reading the analysis…", Make disabled) and plans on main at
/// every change; with something missing a following kind shows the pending summary. Center
/// reads no subjects, so it plans at once and never analyzes. Make remembers, dismisses and
/// hands a `VerticalHandOff` to the editor: the sheet itself never edits and never opens a
/// window.
///
/// **The dev accept** (`-RCDevVerticalAccept YES`, or `in-place`, which unticks Make a copy
/// first; dev tools only): the sheet presses Make once, the first time Make is enabled after the
/// first summary (AU-128's precedent).
final class VerticalVersionSheetController: NSViewController, NSTextFieldDelegate {
    /// The dev-only launch default that presses Make.
    static let devAcceptKey = "RCDevVerticalAccept"
    /// Its value that unticks Make a copy before pressing Make.
    static let devAcceptInPlace = "in-place"
    /// `VerticalVersion.follows`' titles, in its order.
    private static let followTitles = [
        "Subject", "Faces", "People", "Salient Region", "Speaker", "Center",
    ]
    private static let whereEmpties: [(String, FramingWhereEmpty)] = [
        ("Show Whole", .fit), ("Center", .center),
    ]

    private weak var document: ProjectDocument?
    private let make: (VerticalHandOff) -> Void
    private let opened: FollowSubjectSettings
    /// The hand-off this sheet is presented again from, after its analysis (VR-66 (e)).
    private let restoring: VerticalHandOff?
    private let picker: VerticalSpeakerPicker
    /// Speaker's ready readings, per ticked set, each with the reference's microphones named
    /// back as the ticked ones, so a set ticked again is offered its match again (VR-66 (c)).
    private var readings: [[UInt32]: (read: VerticalVersion.SpeakerReading, mics: [UInt32])] = [:]
    /// The subjects with their turns the current Speaker plan read.
    private var speakerSubjects: [UInt32: [String: Any]]?
    private let shapes: [VerticalShape]
    private let canvas: CanvasSnapshot
    private var present: [UInt32] = []
    private var cursor: [UInt32] = []
    private var missing: Set<UInt32> = []
    private var requests: [AnalysisRequest] = []
    private var requestError: String?
    private var subjects: [UInt32: [String: Any]]?
    private var asked: ReelProject?
    /// VR-44 (b)'s survey of the project's graphic modules, made once at `viewDidAppear`.
    private var templates = VerticalVersion.TemplateSurvey()
    private var askedScope: UInt32?
    private var accepted = false
    /// Set by Make: handed to `make` after disappearing.
    private var handOff: VerticalHandOff?

    private let shapePopup = NSPopUpButton(frame: .zero, pullsDown: false)
    private let followPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    private let whereEmptyPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    private let zoomField = NSTextField(string: "")
    private let copyBox = NSButton(checkboxWithTitle: "Make a copy", target: nil, action: nil)
    private let summaryLabel = NSTextField(wrappingLabelWithString: "")
    private var makeButton: NSButton?

    init(
        document: ProjectDocument, restoring: VerticalHandOff? = nil,
        make: @escaping (VerticalHandOff) -> Void
    ) {
        self.document = document
        self.make = make
        self.opened = VerticalVersion.remembered(.standard)
        self.restoring = restoring
        self.canvas = document.project.snapshot.canvas
        self.shapes = VerticalVersion.offered(canvas)
        let ticked = restoring.map(\.settings.mics).flatMap { $0.isEmpty ? nil : $0 }
            popup.action = #selector(controlChanged(_:))
            popup.setAccessibilityIdentifier(id)
        }

        let formatter = NumberFormatter()
        formatter.numberStyle = .decimal
        formatter.allowsFloats = false
        formatter.minimum = NSNumber(value: FollowSubjectSettings.zoomRange.lowerBound * 100)
        formatter.maximum = NSNumber(value: FollowSubjectSettings.zoomRange.upperBound * 100)
        zoomField.formatter = formatter
        zoomField.delegate = self
        zoomField.alignment = .right
        zoomField.integerValue = Int(((start?.zoom ?? 1) * 100).rounded())
        zoomField.widthAnchor.constraint(equalToConstant: 64).isActive = true
        zoomField.setAccessibilityIdentifier("vertical.zoom")
        DSField.style(zoomField)

        copyBox.state = (restoring?.copy ?? true) ? .on : .off
        copyBox.font = DS.sans(13)
        copyBox.target = self
        copyBox.action = #selector(controlChanged(_:))
        copyBox.setAccessibilityIdentifier("vertical.copy")

        summaryLabel.font = DS.sans(12)
        summaryLabel.textColor = DS.textMuted
        summaryLabel.preferredMaxLayoutWidth = sheetWidth - sheetInset * 2
        summaryLabel.stringValue = FollowSubjectSheetController.reading
        summaryLabel.setAccessibilityIdentifier("vertical.summary")

        let grid = makeSheetGrid([
            [fieldLabel("Shape:"), shapePopup],
            [fieldLabel("Follow:"), followPopup],
            [fieldLabel("Zoom:"), sheetRow([zoomField, sheetUnitLabel("%")])],
            [fieldLabel("Where Empty:"), whereEmptyPopup],
            [NSGridCell.emptyContentView, copyBox],
        ])
        let cancel = sheetCancelButton(target: self, action: #selector(cancelClicked(_:)))
        let make = StickerButton(
            title: "Make", style: .primary, target: self, action: #selector(makeClicked(_:)))
        make.isEnabled = false
        makeButton = make
        view = makeSheetView(
            title: "Make Vertical Version",
            hint: "Makes a version of the timeline for a tall or square canvas. Each full-frame "
                + "movie clip follows its subject with eased moves (with Speaker, whoever is "
                + "talking on the ticked microphones), stills and nests are "
                + "centred, and everything else is kept as placed, with a blurred copy behind a "
                + "clip where it shows the whole picture. With Make a copy it opens as a new "
                + "project and this one does not change. One undo step.",
            content: sheetColumn([grid, picker.view, summaryLabel]),
            buttonRow: makeButtonRow(cancel: cancel, apply: make))
        whereEmptyPopup.isEnabled = follow.follow != .center
        picker.view.isHidden = follow.follow != .speaker
    }

    /// VR-39 (d): the targets and the requests, once, on the project and scope the hand-off
    /// carries.
    override func viewDidAppear() {
        super.viewDidAppear()
        guard asked == nil, let document else { return }
        let project = document.project
        asked = project
        askedScope = document.scope
        let targets = VerticalVersion.analysisTargets(project, urls: document.mediaURLs())
        present = targets.present
        missing = targets.missing
        cursor = targets.cursor
        templates = VerticalVersion.templateSurvey(project, store: document.graphicStore)
        do {
            requests = try FramingAnalysis.requests(clips: present, in: document, project: project)
        } catch {
            requestError = error.localizedDescription
        }
        if requestError == nil, requests.isEmpty {
            // The cache folder is needed only for the analysed pictures; a cursor is read
            // from its own file (VR-51).
            let cacheDir = present.isEmpty ? nil : document.cacheDirectory
            let clips = cacheDir == nil ? [] : present
            let cursorClips = cursor
            if clips.isEmpty, cursorClips.isEmpty {
                subjects = [:]
            } else {
                DispatchQueue.global(qos: .userInitiated).async { [weak self] in
                    var read = cacheDir.map {
                        FollowSubject.subjects(clips, in: project, cacheDir: $0)
                    } ?? [:]
                    read.merge(FramingCursor.subjects(cursorClips, in: project)) { _, new in new }
                    DispatchQueue.main.async { self?.didRead(read) }
                }
            }
        }
        refresh()
    }

    private func didRead(_ read: [UInt32: [String: Any]]) {
        subjects = read
        refresh()
    }

    /// The one hand-back: once, after the sheet is gone, never after Cancel.
    override func viewDidDisappear() {
        super.viewDidDisappear()
        guard let handOff else { return }
        self.handOff = nil
        let make = self.make
        DispatchQueue.main.async { make(handOff) }
    }

    // MARK: - Values

    /// What the follow controls say, Zoom inside its range: VR-29's settings, remembered as theirs.
    private var follow: FollowSubjectSettings {
        let range = FollowSubjectSettings.zoomRange
        let percent = Double(zoomField.integerValue)
        let follow = VerticalVersion.follows[max(0, followPopup.indexOfSelectedItem)]
        let empty = Self.whereEmpties[max(0, whereEmptyPopup.indexOfSelectedItem)].1
        return FollowSubjectSettings(
            follow: follow, zoom: min(max(percent / 100, range.lowerBound), range.upperBound),
            whereEmpty: empty)
    }

    /// The step's settings: the chosen shape and the follow controls, with Speaker the ticked
    /// microphones and their confirmed faces.
    private func settings(_ follow: FollowSubjectSettings) -> VerticalSettings? {
        guard !shapes.isEmpty else { return nil }
        let shape = shapes[min(max(0, shapePopup.indexOfSelectedItem), shapes.count - 1)]
        let speaker = follow.follow == .speaker
        return VerticalSettings(
            shape: shape, follow: follow.follow, zoom: follow.zoom, whereEmpty: follow.whereEmpty,
            mics: speaker ? picker.mics : [], micFaces: speaker ? picker.micFaces : nil)
    }

    /// Whether Make hands the analysis on: an analysing follow with requests missing.
    private func pending(_ follow: FollowSubjectSettings) -> Bool {
        VerticalVersion.analyses(follow.follow) && requestError == nil && !requests.isEmpty
    }

    /// Says what Make would do and enables it: the request error, the pending summary,
    /// "Reading the analysis…", or the plan made on main over the document's current handle.
    private func refresh() {
        let follow = self.follow
        let analysing = VerticalVersion.analyses(follow.follow)
        let speaker = follow.follow == .speaker
        whereEmptyPopup.isEnabled = follow.follow != .center
        picker.view.isHidden = !speaker
        speakerSubjects = nil
        var enabled = false
        if let settings = settings(follow) {
            let ticked = (2...VerticalSpeakerPicker.mostMicrophones).contains(settings.mics.count)
            if analysing, let requestError {
                summaryLabel.stringValue = requestError
            } else if speaker, let document,
                VerticalVersion.speakerClips(document.project, settings: settings, missing: missing)
                    .isEmpty
            {
                summaryLabel.stringValue = VerticalVersion.noSpeakerClipSheet
            } else if pending(follow) {
                let size = settings.shape.size(from: canvas)
                summaryLabel.stringValue = VerticalVersion.pendingSummary(
                    files: Set(requests.map(\.media.id)).count, width: size.width,
                    height: size.height, speaker: speaker)
                enabled = !speaker || ticked
            } else if analysing, subjects == nil {
                summaryLabel.stringValue = FollowSubjectSheetController.reading
            } else if speaker {
                switch reading(settings) {
                case .refused(let why):
                    summaryLabel.stringValue = why
                case .ready(let read, _, _):
                    // Read again: the reading's first offer may have preset the faces.
                    let confirmed = self.settings(follow) ?? settings
                    speakerSubjects = read
                    let (made, text) = planned(confirmed)
                    summaryLabel.stringValue = text
                    enabled = made && ticked && confirmed.micFaces != nil
                }
            } else {
                let (made, text) = planned(settings)
                summaryLabel.stringValue = text
                enabled = made
            }
        }
        makeButton?.isEnabled = enabled
        acceptIfAsked()
    }

    /// VR-66 (c): the ticked set's reading, a ready one cached and offered to the picker at every
    /// refresh (`offer` presets a set once, so a repeat does nothing until the set is ticked
    /// again and its rows rebuilt); a refused one read again at every refresh.
    private func reading(_ settings: VerticalSettings) -> VerticalVersion.SpeakerReading {
        let key = settings.mics
        if let cached = readings[key] {
            if case .ready(_, _, let match) = cached.read { picker.offer(match, mics: cached.mics) }
            return cached.read
        }
        guard let document else { return .refused("") }

import Foundation

/// Make Vertical's summary (spec §11 VR-35) and its answer (VR-36): what `plan` did, said as
/// the sheet's and the tool's text and as `make_vertical_version`'s keys. A pure move out of
/// `VerticalVersion+Plan.swift` (road map "creator-jobs" VR5b's toll). Names no `rc_*`.
extension VerticalVersion {
    /// VR-35: the counts, then one line per re-laid switch (VR-54), then one line per entry
    /// with a reason; the graphic counts and lines VR4b's (`templates`, VR-44 (d)).
    static func summary(_ plan: Plan, templates: TemplateReport = TemplateReport()) -> String {
        func count(_ treatment: Treatment) -> Int {
            plan.entries.filter { $0.treatment == treatment }.count
        }
        var text = "Makes a \(plan.width) × \(plan.height) version."
        let followed = count(.followed)
        if followed > 0 { text += " Follows \(counted(followed, "clip"))." }
        if !plan.cursor.isEmpty {
            text += " Follows the cursor in \(counted(plan.cursor.count, "clip")), their own "
                + "zooms and pans replaced."
        }
        if !plan.speaker.isEmpty {
            text += " Follows whoever is talking in \(counted(plan.speaker.count, "clip"))."
        }
        if !plan.relaid.isEmpty {
            text += " Re-lays \(counted(plan.relaid.count, "camera layout")) for the new canvas."
        }
        let whole = count(.whole)
        if whole > 0 { text += " Shows \(counted(whole, "clip")) whole on a blurred copy." }
        let kept = count(.kept)
        if kept > 0 { text += " Keeps \(counted(kept, "clip")) as placed." }
        let refilled = count(.refilled)
        if refilled > 0 { text += " Re-fills \(counted(refilled, "background"))." }
        let removed = count(.removed)
        if removed > 0 {
            text += " Removes \(removed) blurred \(removed == 1 ? "copy" : "copies") the "
                + "framing replaces."
        }
        text += graphicsCounts(plan, templates)
        if plan.backgrounds { text += " Adds a Backgrounds track for the blurred copy." }
        if plan.moreTracks > 0 {
            text += " Adds \(plan.moreTracks) more \(plan.moreTracks == 1 ? "track" : "tracks")"
                + " behind it where clips overlap."
        }
        if plan.reEased > 0 { text += " \(counted(plan.reEased, "action")) re-eased at a cut." }
        if plan.carried > 0 {
            text += " \(counted(plan.carried, "action")) "
                + (plan.carried == 1 ? "carries" : "carry") + " a framing move."
        }
        if let relaid = plan.captions?.relaid.count, relaid > 0 {
            text += " Re-lays \(counted(relaid, "caption track")) for the new canvas."
        }
        let canvas = plan.project.snapshot.canvas
        var lines = [text] + plan.relaid.map { relaidLine($0, canvas: canvas) }
        for entry in plan.entries {
            guard let reason = entry.reason else { continue }
            let why = reason.hasSuffix(".") ? String(reason.dropLast()) : reason
            switch entry.treatment {
            case .notFollowed: lines.append("Clip \(entry.clip) is not followed: \(why).")
            default: lines.append("Clip \(entry.clip) is followed, but \(why).")
            }
        }
        lines += (plan.captions?.kept ?? []).map(CaptionRelayout.keptLine)
        lines += graphicsLines(templates)
        return lines.joined(separator: "\n")
    }

    /// VR-39 (d)'s pending summary, while the analysis is still to be made; with `speaker` it
    /// says the sheet comes back to confirm the microphones' faces (VR-66 (e)).
    static func pendingSummary(files: Int, width: Int, height: Int, speaker: Bool = false)
        -> String
    {
        "Finds the faces, people and shot changes in \(counted(files, "file")) on this Mac "
            + "first, " + (speaker ? "then asks you to confirm who is on each microphone, " : "")
            + "then makes a \(width) × \(height) version."
    }

    /// The answer's keys every door shares (VR-36): `canvas`, `clips` in id order,
    /// `backgrounds`, `more_tracks`, `re_eased`, `moves_carried`, `summary`, `graphics`,
    /// `cursor` (VR-52), `relaid` (VR-54) and `speaker` (VR-64 (f)).
    static func answerFields(_ plan: Plan, templates: TemplateReport = TemplateReport())
        -> [String: Any]
    {
        let clips: [[String: Any]] = plan.entries.map { entry in
            var row: [String: Any] = [
                "clip": Int(entry.clip), "treatment": entry.treatment.rawValue,
            ]
            if let reason = entry.reason { row["reason"] = reason }
            return row
        }
        var fields: [String: Any] = [
            "canvas": ["width": plan.width, "height": plan.height],
            "clips": clips,
            "backgrounds": plan.backgrounds,
            "more_tracks": plan.moreTracks,
            "re_eased": plan.reEased,
            "moves_carried": plan.carried,
            "summary": summary(plan, templates: templates),
            "cursor": plan.cursor.map { Int($0) },
            "relaid": relaidFields(plan.relaid),
            "speaker": plan.speaker.map { framed -> [String: Any] in
                [
                    "clip": Int(framed.clip), "mics": framed.mics.map { Int($0) },
                    "mic_faces": framed.faces.map { Int($0) },
                ]
            },
            "graphics": graphicsFields(plan, templates),
        ]
        if let captions = plan.captions {
            fields["captions"] = CaptionRelayout.answerFields(captions)
        }
        return fields
    }

    static func counted(_ n: Int, _ noun: String) -> String {
        "\(n) \(noun)\(n == 1 ? "" : "s")"
    }
